//! The provider-neutral summary service.
//!
//! A compaction summary is generated by a [`ContextSummarizer`] that the
//! context runtime owns. Since M7.5 (Issue #54) the request boundary is
//! derived directly from the **selected span of complete canonical active
//! messages** of the current Conversation Surface. There is no separate
//! "previous summary" truth: when a previous compaction summary
//! is still active, it is simply one canonical
//! `User(Runtime / CompactionSummary)` message inside the selected span.
//!
//! Summary generation is runtime compaction activity only: it never recurses
//! into `AgentExecution`, never exposes tools, never carries Agent Status or
//! the Skill catalog, never carries provider continuation, and never commits
//! anything to the Message Ledger.

use futures_util::StreamExt;
use futures_util::future::BoxFuture;
use serde::{Deserialize, Serialize};

use crate::context::error::{ContextError, ContextErrorKind};
use crate::message::content::TextBlock;
use crate::message::types::{
    InboundKind, MessageBlock, UserContentBlock, UserMessageBlock, UserSource,
};
use crate::model::event::ModelEvent;
use crate::model::invocation::ResolvedModelInvocation;
use crate::model::types::ModelRequest;
use crate::runtime::cancellation::CancellationSignal;
use crate::runtime::identity::MessageId;

/// One summarizer request.
///
/// The request carries exactly the complete canonical messages of the
/// selected Surface span, in Surface order. Nothing is flattened, nothing is
/// partial, and no hidden previous-summary channel exists beside it.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SummaryRequest {
    /// The selected span of complete canonical active messages, in Surface
    /// order. A still-active previous compaction summary appears here as an
    /// ordinary `User(Runtime / CompactionSummary)` message.
    pub retired: Vec<MessageBlock>,
}

/// The exact provider-neutral model input assembled for one summary request.
///
/// Both compaction planning and [`ModelBackedSummarizer`] consume this value:
/// the fixed instruction, deterministic `SummaryRequest` JSON, and canonical
/// runtime User wrapper therefore cannot drift between estimation and the
/// production invocation.
#[derive(Debug, Clone, PartialEq)]
pub struct SummaryModelInput {
    /// The complete canonical messages sent to the summary model.
    pub messages: Vec<MessageBlock>,
}

impl SummaryRequest {
    /// Whether this request covers at least one canonical message.
    #[must_use]
    pub fn advances_coverage(&self) -> bool {
        !self.retired.is_empty()
    }

    /// Serializes the request envelope deterministically.
    ///
    /// # Panics
    ///
    /// Panics only if canonical runtime-owned data fails to serialize.
    #[must_use]
    pub fn serialized_input(&self) -> String {
        serde_json::to_string(self).expect("summary request serializes")
    }

    /// Assembles the exact canonical model input used by the production
    /// summary invocation.
    #[must_use]
    pub fn model_input(&self) -> SummaryModelInput {
        let instruction = format!("{}\n\n{}", SUMMARY_INSTRUCTION, self.serialized_input());
        SummaryModelInput {
            messages: vec![MessageBlock::User(UserMessageBlock {
                id: MessageId::new("summary-request"),
                content: vec![UserContentBlock::Text(TextBlock { text: instruction })],
                source: UserSource::Runtime,
                kind: InboundKind::Message,
                timestamp: None,
            })],
        }
    }
}

/// The summary service.
pub trait ContextSummarizer: Send + Sync {
    /// Generates the textual summary of one request.
    ///
    /// The returned future is owned by the summarizer and must observe
    /// `cancellation`; cancellation may abort the summary.
    fn summarize(
        &self,
        request: SummaryRequest,
        cancellation: CancellationSignal,
    ) -> BoxFuture<'_, Result<String, ContextError>>;
}

/// The production summarizer backed by a frozen resolved summary-model
/// invocation.
///
/// For automatic compaction the invocation is the attempt's frozen summary
/// resolution. Manual compaction freezes the same session resolution at its
/// idle admission boundary. In `session` mode this is the primary invocation;
/// in `explicit` mode it is the separately resolved summary invocation,
/// optionally narrowed by the context plane's summary output safety cap.
/// There is deliberately no independent "summary provider config" system.
///
/// The summary request is a canonical one-off `ModelRequest`: no tools, no
/// Agent Status, no Skill catalog, no continuation, and a deterministic
/// instruction plus the serialized request input. A refusal (with or without
/// a `RefusalDelta`), a tool request, an invalid stream, a model failure, or
/// an empty/whitespace-only output is a compaction failure, and any provider
/// continuation emitted by the one-off request is discarded: summary
/// activity never contaminates the attempt's continuation or usage state.
pub struct ModelBackedSummarizer {
    invocation: ResolvedModelInvocation,
}

const SUMMARY_INSTRUCTION: &str = "Summarize the following retired conversation history so a later primary model turn can continue the work. Preserve, where applicable, the user's goal; important constraints and preferences; progress and completed work; current work and blockers; key decisions and rationale; important tool outcomes; unresolved threads; next steps; important files, artifacts, paths, and references; and relevant historical runtime observations. Treat Agent Status and other runtime observations as historical evidence, not live authority: for example, observations that a task was running at one time and completed later may be summarized as having run earlier and completed, never as a claim about what is currently running or completed. If an extension Status section is absent from a later observation, do not infer lifecycle completion or disappearance unless that section's explicit contract says absence has that meaning. Use concise factual free-form text. Any organization or headings are prompt guidance only, not a required schema; output only the summary text.";

impl ModelBackedSummarizer {
    /// Creates a summarizer over one resolved summary invocation.
    #[must_use]
    pub const fn new(invocation: ResolvedModelInvocation) -> Self {
        Self { invocation }
    }

    /// The resolved invocation this summarizer sends with.
    #[must_use]
    pub const fn invocation(&self) -> &ResolvedModelInvocation {
        &self.invocation
    }

    /// The deterministic summary instruction text.
    #[must_use]
    pub const fn instruction() -> &'static str {
        SUMMARY_INSTRUCTION
    }

    /// Serializes the request input deterministically for the model.
    ///
    /// The serialization is canonical JSON over runtime-owned types and is
    /// a pure function of the request.
    ///
    /// # Panics
    ///
    /// Panics only if the canonical request input fails to serialize, which
    /// is unreachable for the canonical runtime-owned types.
    #[must_use]
    pub fn serialize_input(request: &SummaryRequest) -> String {
        request.serialized_input()
    }
}

impl ContextSummarizer for ModelBackedSummarizer {
    fn summarize(
        &self,
        request: SummaryRequest,
        cancellation: CancellationSignal,
    ) -> BoxFuture<'_, Result<String, ContextError>> {
        Box::pin(async move {
            let input = request.model_input();
            let model_request = ModelRequest {
                invocation: self.invocation.invocation_config(),
                messages: input.messages,
                tools: Vec::new(),
                // Summary generation is not an inbound Assistant turn: it never
                // carries primary-step dynamic context. Agent Status is a
                // primary-request User fact, and Skill guidance is a
                // primary-request system section; neither belongs here.
                effective_system_prompt: String::new(),
                continuation: None,
            };
            let mut stream = self
                .invocation
                .adapter()
                .stream(model_request, cancellation);
            let mut text = String::new();
            let mut state = SummaryStreamState::default();
            let mut finish_reason = None;
            while let Some(event) = stream.next().await {
                // Malformed canonical orderings are compaction failures,
                // never silently folded into a canonical message.
                state.accept(&event)?;
                match event {
                    ModelEvent::Started
                    | ModelEvent::UsageUpdate { .. }
                    | ModelEvent::ReasoningDelta { .. }
                    | ModelEvent::ContinuationState { .. } => {}
                    ModelEvent::TextDelta { text: delta, .. } => text.push_str(&delta),
                    ModelEvent::RefusalDelta { .. } => {
                        return Err(summary_failed("summary generation refused"));
                    }
                    ModelEvent::ToolCallStarted { .. }
                    | ModelEvent::ToolCallArgumentsDelta { .. }
                    | ModelEvent::ToolCallCompleted { .. } => {
                        return Err(summary_failed("summary generation must not request tools"));
                    }
                    ModelEvent::Completed {
                        finish_reason: reason,
                        ..
                    } => {
                        finish_reason = Some(reason);
                    }
                    ModelEvent::Failed { error } => {
                        return Err(
                            if error.kind == crate::model::error::ModelErrorKind::Cancelled {
                                ContextError::new(
                                    ContextErrorKind::Cancelled,
                                    "summary generation cancelled",
                                )
                            } else {
                                summary_failed(&format!(
                                    "summary generation failed: {}",
                                    error.message
                                ))
                            },
                        );
                    }
                }
            }
            if !state.terminal {
                return Err(summary_failed(
                    "summary stream ended without a terminal event",
                ));
            }
            // The terminal finish reason is authoritative: a refusal with no
            // `RefusalDelta` and a tool-call completion with no delta are
            // still compaction failures, never summaries.
            match finish_reason {
                Some(crate::model::finish::ModelFinishReason::Refusal) => {
                    return Err(summary_failed("summary generation refused"));
                }
                Some(crate::model::finish::ModelFinishReason::ToolCalls) => {
                    return Err(summary_failed("summary generation must not request tools"));
                }
                _ => {}
            }
            // An empty or whitespace-only output erases history; it is never
            // a valid summary.
            if text.trim().is_empty() {
                return Err(summary_failed("summary generation produced no content"));
            }
            Ok(text)
        })
    }
}

fn summary_failed(message: &str) -> ContextError {
    ContextError::new(ContextErrorKind::SummaryFailed, message)
}

/// The canonical stream state of one summary generation.
///
/// Malformed adapter streams must never become durable compaction
/// summary messages: the summary stream must start with `Started` (or a bare
/// terminal `Failed` for a request rejected before provider execution),
/// `Started` occurs at most once, `Completed` requires `Started`, and no
/// event follows the terminal event. This is the same canonical contract
/// the agent loop enforces, kept provider-neutral and without recursing
/// into `AgentExecution`.
#[derive(Debug, Default)]
struct SummaryStreamState {
    started: bool,
    terminal: bool,
}

impl SummaryStreamState {
    /// Accepts one event, validating the canonical stream ordering.
    ///
    /// # Errors
    ///
    /// Returns [`ContextErrorKind::SummaryFailed`] for a malformed
    /// ordering: content before `Started`, a duplicate `Started`,
    /// `Completed` without `Started`, or any event after the terminal.
    fn accept(&mut self, event: &ModelEvent) -> Result<(), ContextError> {
        if self.terminal {
            return Err(summary_failed(
                "summary stream event after the terminal event",
            ));
        }
        match event {
            ModelEvent::Started => {
                if self.started {
                    return Err(summary_failed("duplicate Started in the summary stream"));
                }
                self.started = true;
                Ok(())
            }
            ModelEvent::Failed { .. } => {
                self.terminal = true;
                Ok(())
            }
            ModelEvent::Completed { .. } => {
                if !self.started {
                    return Err(summary_failed("summary stream Completed without Started"));
                }
                self.terminal = true;
                Ok(())
            }
            _ => {
                if !self.started {
                    return Err(summary_failed("summary stream content before Started"));
                }
                Ok(())
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{ModelBackedSummarizer, SummaryRequest};
    use crate::message::content::TextBlock;
    use crate::message::types::{
        InboundKind, MessageBlock, UserContentBlock, UserMessageBlock, UserSource,
    };
    use crate::runtime::identity::MessageId;

    fn request() -> SummaryRequest {
        SummaryRequest {
            retired: vec![MessageBlock::User(UserMessageBlock {
                id: MessageId::new("retired-1"),
                content: vec![UserContentBlock::Text(TextBlock {
                    text: "same payload".to_owned(),
                })],
                source: UserSource::Human,
                kind: InboundKind::Message,
                timestamp: None,
            })],
        }
    }

    /// The shared assembly boundary includes the instruction, serialized
    /// request envelope, and canonical runtime User wrapper exactly once.
    #[test]
    fn summary_model_input_is_deterministic_and_complete() {
        let request = request();
        let first = request.model_input();
        assert_eq!(first, request.model_input());
        assert_eq!(first.messages.len(), 1);
        let MessageBlock::User(wrapper) = &first.messages[0] else {
            panic!("summary input must use the canonical User role");
        };
        assert_eq!(wrapper.id, MessageId::new("summary-request"));
        assert_eq!(wrapper.source, UserSource::Runtime);
        assert_eq!(wrapper.kind, InboundKind::Message);
        let UserContentBlock::Text(text) = &wrapper.content[0] else {
            panic!("summary input must use a text wrapper");
        };
        assert_eq!(
            text.text,
            format!(
                "{}\n\n{}",
                ModelBackedSummarizer::instruction(),
                request.serialized_input()
            )
        );
    }
}
